    data = json.load(f)
# Print structure without the long trace text
def summarize(obj, depth=0, max_depth=3):
    if depth > max_depth:
        print('  '*depth + '...')
        return
    if isinstance(obj, dict):
        for k, v in obj.items():
            if k == 'trace' and isinstance(v, str):
                print('  '*depth + f'{k}: <string len={len(v)}>')
            elif isinstance(v, (dict, list)):
                print('  '*depth + f'{k}:')
                summarize(v, depth+1, max_depth)
            else:
                print('  '*depth + f'{k}: {repr(v)[:100]}')
    elif isinstance(obj, list):
        print('  '*depth + f'[list of {len(obj)} items]')
        if len(obj) > 0:
            summarize(obj[0], depth+1, max_depth)
summarize(data)
"

